-- Function #0
main = function()
	for ItemID, DESC in pairs(tbl) do
		result, msg = AddItem(ItemID, DESC.unidentifiedDisplayName, DESC.unidentifiedResourceName, DESC.identifiedDisplayName, DESC.identifiedResourceName, DESC.slotCount, DESC.ClassNum)
		if not(result) then
			return false, msg
		end
		for k, v in pairs(DESC.unidentifiedDescriptionName) do
			result, msg = AddItemUnidentifiedDesc(ItemID, v)
			if not(result) then
				return false, msg
			end
		end
		for k, v in pairs(DESC.identifiedDescriptionName) do
			result, msg = AddItemIdentifiedDesc(ItemID, v)
			if not(result) then
				return false, msg
			end
		end
		if DESC.EffectID ~= nil then
			result, msg = AddItemEffectInfo(ItemID, DESC.EffectID)
			if not(result) then
				return false, msg
			end
		end
		if DESC.costume ~= nil then
			result, msg = AddItemIsCostume(ItemID, DESC.costume)
			if not(result) then
				return false, msg
			end
		end
		if DESC.PackageID ~= nil then
			result, msg = AddItemPackageID(ItemID, DESC.PackageID)
			if not(result) then
				return false, msg
			end
		end
	end
	return true, "good"
end

-- Function #1
main_server = function()
	for ItemID, DESC in pairs(tbl) do
		result, msg = AddItem(ItemID, DESC.identifiedDisplayName, DESC.slotCount)
		if not(result) then
			return false, msg
		end
	end
	return true, "good"
end
